/// <summary>The native layout of <c>GstQuery</c>.</summary>
/// <remarks>
/// <para>
/// The mirror is only ever read through a pointer into memory that GStreamer
/// owns; it is never allocated, assigned or copied.
/// </para>
/// </remarks>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct QueryRaw
{
    /// <summary>The <c>mini_object</c> field.</summary>
    internal Gst.MiniObjectRaw MiniObject;

    /// <summary>The <c>type</c> field.</summary>
    internal Gst.QueryType Type;
}
